  `contact` varchar(20) DEFAULT NULL,
  `zone` varchar(50) DEFAULT NULL,
  `MeterCube` int(11) NOT NULL,
  `fee` double(10,2) NOT NULL,
  `reg_date` date DEFAULT NULL,
  PRIMARY KEY (`cust_id`)
) ENGINE=InnoDB AUTO_INCREMENT=634 DEFAULT CHARSET=utf8;

