CREATE TABLE `invoice` (
  `invo_id` int(11) NOT NULL AUTO_INCREMENT,
  `cust_id` int(11) NOT NULL,
  `mchore` float DEFAULT NULL,
  `mcdanbe` float DEFAULT NULL,
  `farqi` float DEFAULT NULL,
  `rate` float DEFAULT NULL,
  `balance` float DEFAULT NULL,
  `month_data` date DEFAULT NULL,
  `user_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`invo_id`),
  KEY `cust_id` (`cust_id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `invoice_ibfk_1` FOREIGN KEY (`cust_id`) REFERENCES `customer` (`cust_id`),
  CONSTRAINT `invoice_ibfk_2` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4500 DEFAULT CHARSET=utf8;

