CREATE TABLE `payment` (
  `po_id` int(11) NOT NULL AUTO_INCREMENT,
  `supp_id` int(11) DEFAULT NULL,
  `amoun_pay` int(11) DEFAULT NULL,
  `discount` int(11) DEFAULT NULL,
  `remainder` int(11) DEFAULT NULL,
  `from_acc` int(11) DEFAULT NULL,
  `month_date` date DEFAULT NULL,
  `user_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`po_id`),
  KEY `cust_id` (`supp_id`),
  KEY `acc_id` (`from_acc`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `payment_ibfk_1` FOREIGN KEY (`supp_id`) REFERENCES `customer` (`cust_id`),
  CONSTRAINT `payment_ibfk_2` FOREIGN KEY (`from_acc`) REFERENCES `accoun` (`acc_id`),
  CONSTRAINT `payment_ibfk_3` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;




CREATE TABLE `rate` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `Amount_Type` varchar(20) NOT NULL,
  `rate` float(11,1) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8;

INSERT INTO rate VALUES("1","Dollar","1.3");
INSERT INTO rate VALUES("2","Cash","30.0");



CREATE TABLE `receipt` (
  `rv_id` int(11) NOT NULL AUTO_INCREMENT,
  `cust_id` int(11) DEFAULT NULL,
  `amount` float DEFAULT NULL,
  `discount` float DEFAULT NULL,
  `remainder` float DEFAULT NULL,
  `to_acc` int(11) DEFAULT NULL,
  `month_date` date DEFAULT NULL,
  `user_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`rv_id`),
  KEY `cust_id` (`cust_id`),
  KEY `acc_id` (`to_acc`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `receipt_ibfk_1` FOREIGN KEY (`cust_id`) REFERENCES `customer` (`cust_id`),
  CONSTRAINT `receipt_ibfk_2` FOREIGN KEY (`to_acc`) REFERENCES `accoun` (`acc_id`),
  CONSTRAINT `receipt_ibfk_3` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3408 DEFAULT CHARSET=utf8;

