CREATE TABLE `salarypayment` (
  `sp_id` int(11) NOT NULL AUTO_INCREMENT,
  `emp_id` int(11) DEFAULT NULL,
  `salary` int(11) DEFAULT NULL,
  `from_acc` int(11) DEFAULT NULL,
  `month_date` date DEFAULT NULL,
  `user_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`sp_id`),
  KEY `acc_id` (`from_acc`),
  KEY `user_id` (`user_id`),
  KEY `emp_id` (`emp_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;




CREATE TABLE `supplier` (
  `supp_id` int(11) NOT NULL AUTO_INCREMENT,
  `supp_name` varchar(50) DEFAULT NULL,
  `contact` int(11) DEFAULT NULL,
  `zone` varchar(50) DEFAULT NULL,
  `balance` int(11) NOT NULL,
  `reg_date` date DEFAULT NULL,
  PRIMARY KEY (`supp_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8;




CREATE TABLE `transferaccoun` (
  `check_id` int(11) NOT NULL AUTO_INCREMENT,
  `acc_id` int(11) DEFAULT NULL,
  `acc_name` varchar(50) DEFAULT NULL,
  `day_data` date DEFAULT NULL,
  `tran_amount` int(11) DEFAULT NULL,
  `user_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`check_id`),
  KEY `acc_id` (`acc_id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `transferaccoun_ibfk_1` FOREIGN KEY (`acc_id`) REFERENCES `accoun` (`acc_id`),
  CONSTRAINT `transferaccoun_ibfk_2` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;




CREATE TABLE `users` (
  `user_id` int(11) NOT NULL AUTO_INCREMENT,
  `emp_id` int(11) DEFAULT NULL,
  `username` varchar(20) DEFAULT NULL,
  `password` varchar(10000) DEFAULT NULL,
  `Role` varchar(20) DEFAULT NULL,
  `user_date` date DEFAULT NULL,
  PRIMARY KEY (`user_id`),
  KEY `emp_id` (`emp_id`),
  CONSTRAINT `users_ibfk_1` FOREIGN KEY (`emp_id`) REFERENCES `employees` (`emp_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8;

